            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:HasValueConstraintComponent ;
            sh:sourceShape [ sh:hasValue "\"Metallic inclusion\"" ;
                    sh:maxCount 1 ;
                    sh:minCount 1 ;
                    sh:path <urn:post-answer-review:observed> ] ] .

